// Normalise messages from any entry point (IMAP / Webhook / channel API) into one internal shape.
// IMAP output typically has: from / to / date / subject / text / html
// Webhook channels typically have: from / sender / subject / body / content / message / channel / receivedAt
const items = $input.all().map(({ json }) => {
  const rawBody = json.body ?? json.text ?? json.content ?? json.message ?? '';
  return {
    json: {
      messageId: json.messageId ?? json.uid ?? json.id ?? String(Date.now()),
      channel: json.channel ?? 'email', // email / telegram / web_form / comment ...
      from: json.from ?? json.sender ?? json.fromEmail ?? json.from_email ?? '',
      to: json.to ?? '',
      subject: json.subject ?? json.title ?? '(no subject)',
      body: String(rawBody).slice(0, 20000),
      receivedAt: json.receivedAt ?? json.date ?? json.received_at ?? new Date().toISOString(),
    },
  };
});
return items;

// Human approval gate: false = every draft goes to the review queue (recommended for the first month);
// true = AI drafts are sent automatically. In production read this from a database or env var
// (e.g. {{AUTO_SEND_SWITCH}}), and always force review for low confidence, complaints, or
// messages containing attachments or link requests.
const inputItem = $input.first().json;
const autoSend = false; // set this per your own policy; keep false until you trust the drafts
const reviewRequiredByRule =
  (inputItem.category === 'complaint') ||
  (Number(inputItem.confidence ?? 1) < 0.6);
const effectiveAutoSend = autoSend && !reviewRequiredByRule;
return [{
  json: {
    ...inputItem,
    draft: inputItem.data?.draft ?? inputItem.draft ?? '',
    confidence: inputItem.data?.confidence ?? inputItem.confidence ?? 1,
    autoSend: effectiveAutoSend,
  },
}];

// Human-review branch: mark the draft pending_review, create a queue id, and build the notification text.
const inputItem = $input.first().json;
const queueId = 'q-' + (inputItem.messageId || Date.now());
return [{
  json: {
    ...inputItem,
    queueId: queueId,
    dbStatus: 'pending_review',
    notifyText:
      '[Email triage: awaiting approval] ' + (inputItem.subject || '(no subject)') +
      '\nCategory: ' + (inputItem.category || 'unknown') +
      '\nDraft: ' + String(inputItem.draft || '').slice(0, 2000),
  },
}];
